// Manifest of the pre-cut footage segments in public/footage/ (generated by
// scripts/prepare-footage.sh). Durations are media seconds at 30 fps.
// Tap coordinates are in cropped-source pixel space (1320x2708); `at` is the
// second within the media at which the tap indicator should fire (slightly
// before the UI reacts).

export type Tap = { x: number; y: number; at: number };

export type SegmentInfo = {
  file: string;
  /** Media duration in seconds. Stills have no duration. */
  dur?: number;
  still?: boolean;
  taps?: Tap[];
  dark?: boolean;
};

